/* @autogenerated */
package net.civeira.phylax.integrationtest;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.extension.ConditionEvaluationResult;
import org.junit.jupiter.api.extension.ExecutionCondition;
import org.junit.jupiter.api.extension.ExtensionContext;

/**
 * Habilita los tests que arrancan Quarkus contra la base de datos real solo si la configurada
 * responde: se abre una conexión con los mismos valores que usa {@code config/database.yaml}
 * ({@code DATASOURCE_HOST}, {@code DATASOURCE_PORT}, {@code DATASOURCE_PATH},
 * {@code DATASOURCE_USER}, {@code DATASOURCE_PASS}, o una URL completa en
 * {@code QUARKUS_DATASOURCE_JDBC_URL}), leídos como propiedad del sistema, variable de entorno o
 * línea del {@code .env} del proyecto (Quarkus lo lee, pero no es una variable del proceso). Si no
 * hay base configurada o no responde, los tests se saltan con el motivo en vez de fallar al
 * arrancar.
 *
 * <p>
 * Se evalúa antes de que {@code @QuarkusTest} arranque la aplicación. Se usa con
 * {@code @ExtendWith(RequiresDatabase.class)}, que se hereda. El resultado se calcula una sola vez.
 */
public class RequiresDatabase implements ExecutionCondition {

  /** Tipo de base de datos, driver, URL con host, puerto y base, y puerto por defecto. */
  private static final List<String[]> KINDS = List.of(
      new String[] {"mariadb", "org.mariadb.jdbc.Driver", "jdbc:mariadb://%s:%s/%s", "3306"},
      new String[] {"postgresql", "org.postgresql.Driver", "jdbc:postgresql://%s:%s/%s", "5432"},
      new String[] {"mysql", "com.mysql.cj.jdbc.Driver", "jdbc:mysql://%s:%s/%s", "3306"});

  private static ConditionEvaluationResult result;

  @Override
  public synchronized ConditionEvaluationResult evaluateExecutionCondition(
      ExtensionContext context) {
    if (null == result) {
      result = evaluate();
    }
    return result;
  }

  private static ConditionEvaluationResult evaluate() {
    Optional<String> url =
        setting("QUARKUS_DATASOURCE_JDBC_URL").or(RequiresDatabase::urlFromParts);
    if (url.isEmpty()) {
      return ConditionEvaluationResult.disabled("No database configured (DATASOURCE_PATH or "
          + "QUARKUS_DATASOURCE_JDBC_URL, as system property, environment variable or in .env): "
          + "integration test skipped");
    }
    DriverManager.setLoginTimeout(3);
    try (Connection connection =
        DriverManager.getConnection(url.get(), setting("DATASOURCE_USER").orElse("test_write"),
            setting("DATASOURCE_PASS").orElse("test"))) {
      return ConditionEvaluationResult.enabled("Database reachable at " + url.get());
    } catch (SQLException ex) {
      return ConditionEvaluationResult.disabled("Database configured at " + url.get()
          + " but not reachable (" + ex.getMessage() + "): integration test skipped");
    }
  }

  /** La URL a partir de las partes, con el driver que tenga el proyecto. */
  private static Optional<String> urlFromParts() {
    Optional<String> path = setting("DATASOURCE_PATH");
    if (path.isEmpty()) {
      return Optional.empty();
    }
    for (String[] kind : KINDS) {
      try {
        Class.forName(kind[1]);
      } catch (ClassNotFoundException ex) {
        continue;
      }
      return Optional.of(String.format(kind[2], setting("DATASOURCE_HOST").orElse("localhost"),
          setting("DATASOURCE_PORT").orElse(kind[3]), path.get()));
    }
    return Optional.empty();
  }

  private static Optional<String> setting(String name) {
    Optional<String> value = Optional.ofNullable(System.getProperty(name))
        .or(() -> Optional.ofNullable(System.getProperty(name.toLowerCase().replace('_', '.'))))
        .or(() -> Optional.ofNullable(System.getenv(name)));
    return value.filter(v -> !v.isBlank()).or(() -> dotEnv(name));
  }

  /** El valor de {@code name} en el {@code .env} del directorio de trabajo, si lo hay. */
  private static Optional<String> dotEnv(String name) {
    Path file = Path.of(".env");
    if (!Files.isRegularFile(file)) {
      return Optional.empty();
    }
    try {
      for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
        String trimmed = line.trim();
        if (trimmed.startsWith(name + "=")) {
          String value = trimmed.substring(name.length() + 1).trim();
          return value.isEmpty() ? Optional.empty() : Optional.of(value);
        }
      }
    } catch (IOException ex) {
      return Optional.empty();
    }
    return Optional.empty();
  }
}
